160	// restoreVersions 恢复并校验版本登记。
161	func (s *Store) restoreVersions(disk map[string]diskVersion) error {
162		out := make(map[string]*versionState, len(disk))
163		for k, dv := range disk {
164			if k == "" || dv.Target == "" || k != dv.Target {
165				return fmt.Errorf("%w: invalid upgrade version entry", ErrCorruptStorage)
166			}
167			if err := validateAllowedFrom(dv.Target, dv.AllowedFrom); err != nil {
168				return fmt.Errorf("%w: version %s: %v", ErrCorruptStorage, dv.Target, err)
169			}
170			out[k] = &versionState{Target: dv.Target, AllowedFrom: append([]string(nil), dv.AllowedFrom...)}
171		}
172		s.versions = out
173		return nil
174	}
175	
176	// expectedHist 是从已保存操作结果推导出的应有历史条目。
177	type expectedHist struct {
178		deviceID string
179		stage    string
180		op       diskOp
181	}
182	
183	// restoreCampaigns 恢复活动并做一致性校验。版本、设备引用、操作标识、
184	// 结果历史都必须自洽，否则整个存储拒绝打开。
185	func (s *Store) restoreCampaigns(disk map[string]diskCampaign) error {
186		out := make(map[string]*campaignState, len(disk))
187		for id, dc := range disk {
188			if id == "" || dc.ID != id {
189				return fmt.Errorf("%w: campaign id mismatch", ErrCorruptStorage)
190			}
191			if dc.Operator == "" || dc.Target == "" || dc.BatchSize <= 0 {
192				return fmt.Errorf("%w: campaign %s invalid", ErrCorruptStorage, id)
193			}
194			if dc.CreatedAt.IsZero() || dc.WindowStart.IsZero() || dc.WindowEnd.IsZero() || dc.Deadline.IsZero() {
195				return fmt.Errorf("%w: campaign %s missing time", ErrCorruptStorage, id)
196			}
197			if !dc.WindowStart.Before(dc.WindowEnd) || !dc.Deadline.After(dc.CreatedAt) {
198				return fmt.Errorf("%w: campaign %s invalid time range", ErrCorruptStorage, id)
199			}
200			if _, ok := s.versions[dc.Target]; !ok {
201				return fmt.Errorf("%w: campaign %s target %s missing", ErrCorruptStorage, id, dc.Target)
202			}
203			if dc.Status != CampaignRunning && dc.Status != CampaignSucceeded && dc.Status != CampaignFailed {
204				return fmt.Errorf("%w: campaign %s bad status", ErrCorruptStorage, id)
205			}
206			if dc.IDScheme != opIDSchemeLegacy && dc.IDScheme != opIDSchemeV2 {
207				return fmt.Errorf("%w: campaign %s unknown operation id scheme", ErrCorruptStorage, id)
208			}
209			if dc.Ended == (dc.Status == CampaignRunning) {
210				return fmt.Errorf("%w: campaign %s ended/status mismatch", ErrCorruptStorage, id)
211			}
212			if len(dc.Devices) == 0 {
213				return fmt.Errorf("%w: campaign %s has no devices", ErrCorruptStorage, id)
214			}
215			c := &campaignState{
216				ID:                dc.ID,
217				Operator:          dc.Operator,
218				Target:            dc.Target,
219				CreatedAt:         dc.CreatedAt,
220				BatchSize:         dc.BatchSize,
221				WindowStart:       dc.WindowStart,
222				WindowEnd:         dc.WindowEnd,
223				Deadline:          dc.Deadline,
224				RollbackOnFailure: dc.RollbackOnFailure,
225				idScheme:          dc.IDScheme,
226				LastTime:          dc.LastTime,
227				Status:            dc.Status,
228				Ended:             dc.Ended,
229				EndedAt:           dc.EndedAt,
230				index:             map[string]int{},
231			}
232			// 旧记录可能没有时间基线：缺省（零值）时仍以创建时间作为基线。
233			// 基线与各业务记录时间是否自洽在设备与历史全部恢复后统一检查。
234			if c.LastTime.IsZero() {
235				c.LastTime = c.CreatedAt
236			}
237			seen := map[string]bool{}
238			// expected 按操作标识收集每个已有结果（HasResult）的下载/安装/回滚
239			// 操作所对应的唯一应有历史条目，随后与保存的结果历史逐条对账。
240			expected := map[string]expectedHist{}
241			for i, dd := range dc.Devices {
242				if dd.DeviceID == "" || seen[dd.DeviceID] {
243					return fmt.Errorf("%w: campaign %s device list invalid", ErrCorruptStorage, id)
244				}
245				seen[dd.DeviceID] = true
246				if _, ok := s.devices[dd.DeviceID]; !ok {
247					return fmt.Errorf("%w: campaign %s device %s missing", ErrCorruptStorage, id, dd.DeviceID)
248				}
249				if dd.Batch != i/dc.BatchSize {
250					return fmt.Errorf("%w: campaign %s batch mismatch", ErrCorruptStorage, id)
251				}
252				if !validDeviceStatus(dd.Status) {
253					return fmt.Errorf("%w: campaign %s bad device status", ErrCorruptStorage, id)
254				}
255				if dd.Phase != StageDownload && dd.Phase != StageInstall && dd.Phase != StageRollback {
256					return fmt.Errorf("%w: campaign %s bad phase", ErrCorruptStorage, id)
257				}
258				if dc.IDScheme == opIDSchemeV2 {
259					// 新方案：标识必须是无歧义编码且恰好归属本活动、本设备、本阶段。
260					if !validV2OpID(dd.Download.ID, id, dd.DeviceID, StageDownload) ||
261						!validV2OpID(dd.Install.ID, id, dd.DeviceID, StageInstall) ||
262						!validV2OpID(dd.Rollback.ID, id, dd.DeviceID, StageRollback) {
263						return fmt.Errorf("%w: campaign %s operation id mismatch", ErrCorruptStorage, id)
264					}
265				} else {
266					wantDL := operationID(id, dd.DeviceID, StageDownload)
267					wantIN := operationID(id, dd.DeviceID, StageInstall)
268					wantRB := operationID(id, dd.DeviceID, StageRollback)
269					if dd.Download.ID != wantDL || dd.Install.ID != wantIN {
270						return fmt.Errorf("%w: campaign %s operation id mismatch", ErrCorruptStorage, id)
271					}
272					if dc.RollbackOnFailure {
273						if dd.Rollback.ID != wantRB {
274							return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
275						}
276					} else if dd.Rollback.ID != "" && dd.Rollback.ID != wantRB {
277						// 未开启回滚的旧活动：回滚标识允许缺省或等于旧稳定标识。
278						return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
279					}
280				}
281				if !dc.RollbackOnFailure {
282					// 未开启回滚的活动（含旧存储）不得残留任何回滚进展。
283					if dd.RollbackTarget != "" ||
284						dd.Rollback.Claimed || dd.Rollback.HasResult ||
285						dd.Status == DeviceAwaitingRollback || dd.Status == DeviceRollingBack ||
286						dd.Phase == StageRollback || isRollbackTerminal(dd.Status) {
287						return fmt.Errorf("%w: campaign %s rollback state in non-rollback campaign", ErrCorruptStorage, id)
288					}
289				}
290				// 终态设备必须带时间；失败还须带阶段与原因。
291				if isTerminal(dd.Status) && dd.At.IsZero() {
292					return fmt.Errorf("%w: campaign %s terminal without time", ErrCorruptStorage, id)
293				}
294				if dd.Status == DeviceFailed && dd.Reason == "" {
295					return fmt.Errorf("%w: campaign %s failure without reason", ErrCorruptStorage, id)
296				}
297				if (dd.Status == DeviceRollbackFailed || dd.Status == DeviceRollbackTimeout ||
298					dd.Status == DeviceAwaitingRollback) && dd.Reason == "" {
299					return fmt.Errorf("%w: campaign %s rollback without reason", ErrCorruptStorage, id)
300				}
301				if dd.Status == DeviceSucceeded &&
302					!(dd.Download.HasResult && dd.Download.Success && dd.Install.HasResult && dd.Install.Success) {
303					return fmt.Errorf("%w: campaign %s succeeded device without results", ErrCorruptStorage, id)
304				}
305				if dd.Status == DeviceFailed {
306					// 标为 failed 的设备只能是下载失败，或未开启失败回滚时直接结束
307					// 的安装失败：阶段只能是 download 或 install（回滚阶段失败另有
308					// rollback_failed 状态；开启回滚时安装失败进入回滚流程，也不会
309					// 以此状态结束），且必须对应本设备在本活动中已接受的该阶段失败
310					// 结果。设备状态中的失败原因必须与结果原因逐字一致，失败时间
311					// 必须表示首次接受该结果的同一实际时刻。不能把下载失败写成回滚
312					// 阶段，也不能借同批其他设备、其他活动的失败记录或设备当前影子
313					// 版本来解释它。矛盾一律拒绝打开整个存储，不能跳过该设备提供
314					// 其余记录，也不能改写原因、挪动时间或删去历史使其打开。
315					if err := validateFailedDeviceDisk(id, dd); err != nil {
316						return err
317					}
318				}
319				// pending（等待下载）与 downloading（下载中）都必须停留在下载阶段，
320				// 且只能依据本设备在本活动保存的下载操作记录核对。
321				if err := validateDownloadStageDisk(id, dd); err != nil {
322					return err
323				}
324				// ready（等待安装）与 installing（正在安装）都必须停留在安装阶段，
325				// 且只能依据本设备在本活动保存的下载/安装操作记录核对。
326				if err := validateInstallStageDisk(id, dd); err != nil {
327					return err
328				}
329				ops := []diskOp{dd.Download, dd.Install}
330				if dc.RollbackOnFailure {
331					ops = append(ops, dd.Rollback)
332				}
333				for _, o := range ops {
334					if o.HasResult {
335						if !o.Claimed {
336							return fmt.Errorf("%w: campaign %s unclaimed result", ErrCorruptStorage, id)
337						}
338						if o.At.IsZero() {
339							return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
340						}
341						if !o.Success && o.Reason == "" {
342							return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
343						}
344					}
345					if o.Claimed && o.ClaimedAt.IsZero() {
346						return fmt.Errorf("%w: campaign %s claim without time", ErrCorruptStorage, id)
347					}
348				}
349				if dd.Install.HasResult && !(dd.Download.HasResult && dd.Download.Success) {
350					return fmt.Errorf("%w: campaign %s install before download", ErrCorruptStorage, id)
351				}
352				if dd.Install.Claimed && !(dd.Download.HasResult && dd.Download.Success) {
353					return fmt.Errorf("%w: campaign %s install claimed before download", ErrCorruptStorage, id)
354				}
355				if dd.Install.HasResult && dd.Install.Success {
356					if dd.Install.ResultVersion != dc.Target {
357						return fmt.Errorf("%w: campaign %s install version mismatch", ErrCorruptStorage, id)
358					}
359					if _, ok := decodeObject(dd.Install.ResultConfig); !ok {
360						return fmt.Errorf("%w: campaign %s install config invalid", ErrCorruptStorage, id)
361					}
362					if err := checkSuccessReport(id, dd, dd.Install, StageInstall, s.devices[dd.DeviceID]); err != nil {
363						return err
364					}
365				}
366				if dc.RollbackOnFailure {
367					if err := validateRollbackDisk(id, dd); err != nil {
368						return err
369					}
370				}
371				if dd.Rollback.HasResult && dd.Rollback.Success {
372					// 未开启回滚的活动存在回滚结果已在上方拒绝；这里只需核对
373					// 开启回滚的活动中已接受的回滚成功记录。
374					if err := checkSuccessReport(id, dd, dd.Rollback, StageRollback, s.devices[dd.DeviceID]); err != nil {
375						return err
376					}
377				}
378				rbOp := decodeOp(dd.Rollback)
379				if !dc.RollbackOnFailure {
380					// 与创建路径一致：内存中始终持有本方案稳定的回滚操作标识。
381					if dc.IDScheme == opIDSchemeV2 {
382						rbOp = opState{ID: dd.Rollback.ID}
383					} else {
384						rbOp = opState{ID: operationID(id, dd.DeviceID, StageRollback)}
385					}
386				}
387				cd := &campaignDevice{
388					DeviceID:       dd.DeviceID,
389					Batch:          dd.Batch,
390					Status:         dd.Status,
391					Phase:          dd.Phase,
392					Reason:         dd.Reason,
393					At:             dd.At,
394					Download:       decodeOp(dd.Download),
395					Install:        decodeOp(dd.Install),
396					Rollback:       rbOp,
397					RollbackTarget: dd.RollbackTarget,
398				}
399				c.index[cd.DeviceID] = len(c.Devices)
400				c.Devices = append(c.Devices, cd)
401				// 每个已有结果的操作都应当恰好对应一条结果历史；
402				// 已领取未完成、超时或因前批失败而未执行的阶段没有结果，不入账。
403				addExpected := func(o diskOp, stage string) {
404					if !o.HasResult {
405						return
406					}
407					expected[o.ID] = expectedHist{deviceID: dd.DeviceID, stage: stage, op: o}
408				}
409				addExpected(dd.Download, StageDownload)
410				addExpected(dd.Install, StageInstall)
411				if dc.RollbackOnFailure {
412					addExpected(dd.Rollback, StageRollback)
413				}
414			}
415			// seenHistory 记录已经与保存历史对过账的操作标识。
416			seenHistory := map[string]bool{}
417			var prevAt time.Time
418			for i, dr := range dc.Results {
419				if dr.At.IsZero() {
420					return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
421				}
422				// 历史按接受顺序保存：时间不得倒退；同一时刻按保存次序排列。
423				if i > 0 && dr.At.Before(prevAt) {
424					return fmt.Errorf("%w: campaign %s result history out of order", ErrCorruptStorage, id)
425				}
426				prevAt = dr.At
427				if _, ok := c.index[dr.DeviceID]; !ok {
428					return fmt.Errorf("%w: campaign %s result device mismatch", ErrCorruptStorage, id)
429				}
430				if dr.Stage != StageDownload && dr.Stage != StageInstall && dr.Stage != StageRollback {
431					return fmt.Errorf("%w: campaign %s result stage invalid", ErrCorruptStorage, id)
432				}
433				if dr.Stage == StageRollback && !dc.RollbackOnFailure {
434					return fmt.Errorf("%w: campaign %s rollback result in non-rollback campaign", ErrCorruptStorage, id)
435				}
436				if dc.IDScheme == opIDSchemeLegacy {
437					// 旧方案标识可按（活动, 设备, 阶段）直接重算；新方案标识的
438					// 归属已在设备操作校验中确认，这里靠下方的历史对账锚定。
439					if wantOp := operationID(id, dr.DeviceID, dr.Stage); dr.OperationID != wantOp {
440						return fmt.Errorf("%w: campaign %s result op id mismatch", ErrCorruptStorage, id)
441					}
442				}
443				if seenHistory[dr.OperationID] {
444					return fmt.Errorf("%w: campaign %s duplicated result history", ErrCorruptStorage, id)
445				}
446				seenHistory[dr.OperationID] = true
447				// 历史必须对应该设备该阶段实际已有的结果：多出记录、设备或阶段不符
448				// 都按损坏处理，不能通过删历史或补结果把矛盾隐藏起来。
449				want, ok := expected[dr.OperationID]
450				if !ok {
451					return fmt.Errorf("%w: campaign %s result history without operation result", ErrCorruptStorage, id)
452				}
453				if want.deviceID != dr.DeviceID || want.stage != dr.Stage {
454					return fmt.Errorf("%w: campaign %s result history stage mismatch", ErrCorruptStorage, id)
455				}
456				if !dr.Success && dr.Reason == "" {
457					return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
458				}
459				o := want.op
460				if o.Success != dr.Success {
461					return fmt.Errorf("%w: campaign %s result history success mismatch", ErrCorruptStorage, id)
462				}
463				// 失败原因必须一致。成功结果的原因不进入历史（提交路径亦不拒绝
464				// 成功结果附带原因），故只对失败结果比对原因。
465				if !o.Success && o.Reason != dr.Reason {
466					return fmt.Errorf("%w: campaign %s result history reason mismatch", ErrCorruptStorage, id)
467				}
468				// 时间按同一时刻判断，不因时区表示不同而冲突。
469				if !o.At.Equal(dr.At) {
470					return fmt.Errorf("%w: campaign %s result history time mismatch", ErrCorruptStorage, id)
471				}
472				// 安装或回滚成功时记录的版本必须与当次操作接受的版本一致。
473				if dr.Success && (dr.Stage == StageInstall || dr.Stage == StageRollback) {
474					if dr.Version != o.ResultVersion || dr.Version == "" {
475						return fmt.Errorf("%w: campaign %s result history version mismatch", ErrCorruptStorage, id)
476					}
477				} else if dr.Version != "" {
478					// 下载成功及任何失败结果都不携带版本。
479					return fmt.Errorf("%w: campaign %s result history with unexpected version", ErrCorruptStorage, id)
480				}
481				c.Results = append(c.Results, ResultRecord{
482					DeviceID:    dr.DeviceID,
483					OperationID: dr.OperationID,
484					Stage:       dr.Stage,
485					Success:     dr.Success,
486					Reason:      dr.Reason,
487					Version:     dr.Version,
488					At:          dr.At,
489				})
490			}
491			// 反向对账：每个已有结果的操作都必须恰好有一条历史；缺少记录即损坏。
492			for opID, want := range expected {
493				if !seenHistory[opID] {
494					return fmt.Errorf("%w: campaign %s device %s %s result missing history",
495						ErrCorruptStorage, id, want.deviceID, want.stage)
496				}
497			}
498			// 活动整体结论必须与设备进度一致：与接收设备结果时的 settle 共用
499			// campaignConclusion 的同一套结论规则——任一设备仍处于非终态（等待下载、
500			// 下载中、等待安装、安装中、等待回滚、回滚中），活动必须 running 且
501			// Ended 为 false；全部设备终态时活动必须已结束，且只有每台设备都
502			// succeeded 才能 succeeded，其余组合（失败、超时、未执行，以及回滚
503			// 成功/失败/超时——回滚成功只是恢复原版本，不算本次升级成功）只能
504			// failed。设备离线或维护窗口结束不改变这一判断。
505			wantEnded, wantStatus := campaignConclusion(c)
506			if !wantEnded {
507				if c.Ended || c.Status != wantStatus {
508					return fmt.Errorf("%w: campaign %s ended while devices unfinished", ErrCorruptStorage, id)
509				}
510			} else {
511				if !c.Ended || c.Status != wantStatus {
512					return fmt.Errorf("%w: campaign %s status %s does not match device results",
513						ErrCorruptStorage, id, c.Status)
514				}
515			}
516			// 批次放行顺序必须与保存的升级结果自洽：任一设备首次领取下载时，
517			// 较早批次的每台设备都必须已经首次接受“安装成功”结果，且其成功
518			// 时间不晚于该次下载领取时间。只看活动保存的结果，不看设备当前在线
519			// 状态或当前版本；下载成功、安装中、安装失败后等待回滚、已回滚等
520			// 都不算放行。该核对对仍在执行和已结束的活动都生效，下载后来的
521			// 成功、失败或超时不能掩盖首次领取时越批的矛盾。
522			if err := checkCampaignBatchRelease(id, c); err != nil {
523				return err
524			}
525			// 每个已领取操作的首次领取时间必须落在活动保存的原维护窗口内；
526			// 窗口外的首次领取不能当作有效进度接受，也不能靠挪动领取时间、
527			// 撤销领取或重写进度来消除矛盾。
528			if err := checkCampaignClaimWindow(id, c); err != nil {
529				return err
530			}
531			// 时间基线必须能解释全部已存在的业务记录，否则重开后本应被拒绝的
532			// 旧时间请求又能推进活动。不能抬高基线或改写任何记录来掩盖矛盾。
533			if err := checkCampaignTimeBaseline(id, c); err != nil {
534				return err
535			}
536			// 已接受结果的操作，其首次结果发生时间不得早于该操作自己的首次领取
537			// 时间；结果先于领取发生在因果上不可能，不能靠其他设备的领取时间、
538			// 设备影子的最近上报时间或活动结束时间把它“合法化”。
539			if err := checkCampaignResultOrder(id, c); err != nil {
540				return err
541			}
542			// 已接受结果的操作，其首次结果发生时间还必须严格早于活动截止时间；
543			// 截止时刻及以后正常提交路径不再接收结果，已有存储中的迟到结果不能
544			// 当作有效进度读取。
545			if err := checkCampaignResultDeadline(id, c); err != nil {
546				return err
547			}
548			out[id] = c
549		}
550		// 设备不能同时参加多个未结束活动。
551		busy := map[string]string{}
552		for id, c := range out {
553			if c.Ended {
554				continue
555			}
556			for _, cd := range c.Devices {
557				if other, ok := busy[cd.DeviceID]; ok {
558					return fmt.Errorf("%w: device %s in active campaigns %s and %s",
559						ErrCorruptStorage, cd.DeviceID, other, id)
560				}
561				busy[cd.DeviceID] = id
562			}
563		}
564		s.campaigns = out
565		return nil
566	}
567	
568	// checkCampaignBatchRelease 核对活动的批次放行顺序与保存的升级结果自洽：
569	// 任一已经领取过下载的设备，在其首次领取下载时，所有较早批次的设备都必须
570	// 已经成功完成安装，且每台前序设备首次接受安装成功结果的时间不晚于该次
571	// 下载的首次领取时间。只按活动保存的升级结果判断：设备当前是否在线、当前
572	// 版本是否恰好等于目标版本都不能替代前序安装成功；前序设备仅下载成功、
573	// 正在安装、安装失败后等待回滚或已经回滚成功均不满足放行条件。
574	// 尚未领取下载的设备（正常等待后批、因前批失败而未执行、未领取即随截止
575	// 超时）不参与核对，也不能仅因前批没有成功而拒绝。时间按同一时刻比较，
576	// 时区写法不同不视为矛盾；同一时刻合法。核对对仍在执行和已结束的活动都
577	// 生效，下载后来成功、失败或超时都不能掩盖首次领取时越过前批的问题。
578	func checkCampaignBatchRelease(campaignID string, c *campaignState) error {
579		for _, cd := range c.Devices {
580			if !cd.Download.Claimed || cd.Download.ClaimedAt.IsZero() {
581				continue
582			}
583			claimedAt := cd.Download.ClaimedAt
584			for _, prev := range c.Devices {
585				if prev.Batch >= cd.Batch {
586					// 同批设备各自推进，不等待同批其他设备；更晚批次不相关。
587					continue
588				}
589				if !(prev.Install.HasResult && prev.Install.Success) {
590					return fmt.Errorf("%w: campaign %s device %s download claimed while previous-batch device %s not installed",
591						ErrCorruptStorage, campaignID, cd.DeviceID, prev.DeviceID)
592				}
593				// time.Time 的比较按绝对时刻进行，不因时区写法不同而拒绝
594				// 相同时刻；安装成功时刻晚于下载领取时刻即属越批领取，相等合法。
595				if prev.Install.At.After(claimedAt) {
596					return fmt.Errorf("%w: campaign %s device %s download claimed at %s before device %s install succeeded at %s",
597						ErrCorruptStorage, campaignID, cd.DeviceID,
598						claimedAt.Format(time.RFC3339Nano), prev.DeviceID, prev.Install.At.Format(time.RFC3339Nano))
599				}
600			}
601		}
602		return nil
603	}
604	
605	// checkCampaignClaimWindow 核对每个已领取的下载/安装/回滚操作的首次领取时间
606	// 都落在活动保存的原维护窗口 [start, end) 内：开始时刻包含、结束时刻不包含。
607	// 首次领取必须遵守维护窗口——早于开始或恰好到达、晚于结束的领取记录都使整个
608	// 存储损坏，即使其余状态与结果历史完全自洽、活动仍在执行或已成功/失败结束、
609	// 该操作后来成功、失败或超时，也不能把窗口外的首次领取当作有效进度接受，
610	// 更不能通过挪动领取时间、撤销领取、删去活动或重写进度来消除矛盾。
611	// 这项核对只针对真正首次领取的时刻：尚未领取的操作没有领取时间（等待下载、
612	// 等待安装、等待回滚及未领取便结束的记录），属正常缺省，不参与核对；未开启
613	// 回滚的活动内存中只有缺省的回滚操作标识，不算已领取。已经在窗口内领取的
614	// 操作，后来在窗口外的重复查询、截止前的结果接受以及活动结束时间都不要求
615	// 重新满足窗口。比较按绝对时刻进行，时区写法不同不视为矛盾。
616	func checkCampaignClaimWindow(campaignID string, c *campaignState) error {
617		for _, cd := range c.Devices {
618			ops := []struct {
619				stage string
620				op    *opState
621			}{
622				{StageDownload, &cd.Download},
623				{StageInstall, &cd.Install},
624				{StageRollback, &cd.Rollback},
625			}
626			for _, item := range ops {
627				if !item.op.Claimed {
628					continue
629				}
630				at := item.op.ClaimedAt
631				// 窗口为 [start, end)：恰好到达开始合法，恰好到达结束不合法。
632				// time.Time 的比较按绝对时刻进行，同一时刻的不同时区写法结果相同。
633				if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
634					return fmt.Errorf("%w: campaign %s device %s %s first claimed at %s outside maintenance window [%s, %s)",
635						ErrCorruptStorage, campaignID, cd.DeviceID, item.stage,
636						at.Format(time.RFC3339Nano),
637						c.WindowStart.Format(time.RFC3339Nano),
638						c.WindowEnd.Format(time.RFC3339Nano))
639				}
640			}
641		}
642		return nil
643	}
644	
645	// checkCampaignTimeBaseline 校验活动时间基线（已接受的最新时间）与保存的
646	// 业务记录自洽：基线必须不早于创建时间、任一设备已经领取下载/安装/回滚的
647	// 时间、任一操作首次接受结果的时间、设备当前状态中已记录的时间；活动已结束
648	// 时还必须不早于保存的结束时间。只比较确实存在的记录：尚未领取的操作没有
649	// 领取时间、尚未接受结果的操作没有结果时间、新建且尚未推进的设备允许没有
650	// 状态时间，这些正常缺省值不导致打开失败。比较按绝对时刻进行，相等合法。
651	func checkCampaignTimeBaseline(campaignID string, c *campaignState) error {
652		baseline := c.LastTime
653		bad := func(format string, args ...any) error {
654			msg := fmt.Sprintf(format, args...)
655			return fmt.Errorf("%w: campaign %s time baseline %s %s",
656				ErrCorruptStorage, campaignID, baseline.Format(time.RFC3339Nano), msg)
657		}
658		if baseline.Before(c.CreatedAt) {
659			return bad("before creation time %s", c.CreatedAt.Format(time.RFC3339Nano))
660		}
661		if c.Ended && !c.EndedAt.IsZero() && baseline.Before(c.EndedAt) {
662			return bad("before end time %s", c.EndedAt.Format(time.RFC3339Nano))
663		}
664		for _, cd := range c.Devices {
665			if !cd.At.IsZero() && baseline.Before(cd.At) {
666				return bad("before device %s state time %s",
667					cd.DeviceID, cd.At.Format(time.RFC3339Nano))
668			}
669			// 已领取（含尚未完成）的操作一定接受过携带领取时刻的请求；
670			// 已接受结果的操作还必须比较首次接受结果的时间。未领取/未接受
671			// 的操作对应时间为零值，属正常缺省，跳过比较。
672			ops := []struct {
673				stage string
674				op    *opState
675			}{
676				{StageDownload, &cd.Download},
677				{StageInstall, &cd.Install},
678				{StageRollback, &cd.Rollback},
679			}
680			for _, item := range ops {
681				if !item.op.ClaimedAt.IsZero() && baseline.Before(item.op.ClaimedAt) {
682					return bad("before device %s %s claim time %s",
683						cd.DeviceID, item.stage, item.op.ClaimedAt.Format(time.RFC3339Nano))
684				}
685				if item.op.HasResult && !item.op.At.IsZero() && baseline.Before(item.op.At) {
686					return bad("before device %s %s result time %s",
687						cd.DeviceID, item.stage, item.op.At.Format(time.RFC3339Nano))
688				}
689			}
690		}
691		return nil
692	}
693	
694	// checkCampaignResultOrder 校验每个已经接受结果的下载/安装/回滚操作，其首次
695	// 结果发生时间都不早于该操作自己的首次领取时间：同一活动、同一设备、同一阶段
696	// 的两个时刻直接比较，成功与失败适用同一规则。结果先于领取在因果上不可能，
697	// 必须使整个存储拒绝打开；不能用其他设备的领取时间、设备影子的最近上报时间、
698	// 活动的最新时间或结束时间替代这两个时刻，也不能通过修改时间、删除结果历史、
699	// 撤销领取或改变设备状态让记录变得合法。后来安装成功或回滚完成同样不能掩盖
700	// 早先阶段的矛盾，因此该核对对仍在执行和已结束的活动都生效。
701	// 只比较该操作自己确实存在的两个时刻：尚未接受结果（含已领取未完成、随后因
702	// 截止超时）的操作没有结果时间，尚未领取的等待步骤没有领取时间，均属正常
703	// 缺省，跳过核对。首次领取时因版本不兼容而直接形成的下载失败，领取与失败
704	// 可以是同一时刻；两时刻相等合法。已领取操作在窗口结束后、截止前提交结果
705	// 不受限制——本核对不要求结果落在维护窗口内。比较按绝对时刻进行，时区写法
706	// 不同不视为矛盾。重复提交不覆盖首次记录，这里使用的就是首次接受的两个时刻。
707	func checkCampaignResultOrder(campaignID string, c *campaignState) error {
708		for _, cd := range c.Devices {
709			ops := []struct {
710				stage string
711				op    *opState
712			}{
713				{StageDownload, &cd.Download},
714				{StageInstall, &cd.Install},
715				{StageRollback, &cd.Rollback},
716			}
717			for _, item := range ops {
718				o := item.op
719				// 未接受结果（含已领取未完成、超时）或未领取的操作不参与核对：
720				// HasResult 为 true 时上方的操作校验已保证 Claimed 且两个时间非零。
721				if !o.HasResult {
722					continue
723				}
724				// time.Time 的比较按绝对时刻进行：结果早于首次领取即损坏，
725				// 相同时刻的不同时区写法结果相同，相等合法。
726				if o.At.Before(o.ClaimedAt) {
727					return fmt.Errorf("%w: campaign %s device %s %s result at %s before first claim at %s",
728						ErrCorruptStorage, campaignID, cd.DeviceID, item.stage,
729						o.At.Format(time.RFC3339Nano), o.ClaimedAt.Format(time.RFC3339Nano))
730				}
731			}
732		}
733		return nil
734	}
735	
736	// checkCampaignResultDeadline 校验每个已经接受结果的下载/安装/回滚操作，其首次
737	// 结果发生时间都严格早于所属活动的截止时间：正常提交路径在截止时刻及以后不再
738	// 把结果接收为操作结果（已领取未完成的操作随截止记为超时），因此已有存储中
739	// 等于或晚于截止的结果时间不可能由正常提交产生，必须使整个存储拒绝打开。
740	// 成功与失败适用同一规则；恰好等于截止时间也属于迟到。比较按绝对时刻进行，
741	// 时区写法不同不改变判断。该核对对仍在执行和已结束的活动都生效：设备后来
742	// 安装成功、回滚完成或当前版本恰好等于目标版本，都不能让早先的迟到结果合法。
743	// 只比较操作自己确实保存的结果时间：已领取但尚无结果、随后因截止而超时的操作
744	// 没有结果时间，属正常缺省，不参与核对；活动的超时状态时间与结束时间可以等于
745	// 或晚于截止，普通设备上报也不受这项限制，这些时间不能代替操作结果时间参与
746	// 判断。截止前已接受的结果后来重复提交时不改写首次记录，这里使用的是首次接受
747	// 的时刻，不按重复提交时间判断。命中任意一条都必须返回 ErrCorruptStorage，
748	// 不能通过删除迟到结果、调整时间或把设备改成超时来继续打开。
749	func checkCampaignResultDeadline(campaignID string, c *campaignState) error {
750		for _, cd := range c.Devices {
751			ops := []struct {
752				stage string
753				op    *opState
754			}{
755				{StageDownload, &cd.Download},
756				{StageInstall, &cd.Install},
757				{StageRollback, &cd.Rollback},
758			}
759			for _, item := range ops {
760				o := item.op
761				// 未接受结果（含已领取未完成、随后超时）的操作没有结果时间，
762				// 属正常缺省，跳过核对。
763				if !o.HasResult {
764					continue
765				}
766				// time.Time 的比较按绝对时刻进行：结果不早于截止（相等或更晚）
767				// 即属迟到，同一时刻的不同时区写法判断相同。
768				if !o.At.Before(c.Deadline) {
769					return fmt.Errorf("%w: campaign %s device %s %s result at %s not before deadline %s",
770						ErrCorruptStorage, campaignID, cd.DeviceID, item.stage,
771						o.At.Format(time.RFC3339Nano), c.Deadline.Format(time.RFC3339Nano))
772				}
773			}
774		}
775		return nil
776	}
777	
778	// checkSuccessReport 核对一条已接受的安装/回滚成功记录保存的附带上报与
779	// 对应设备影子最近接受的上报之间的关系。序号必须是正整数且不大于设备最近
780	// 接受的序号：缺失、为零或大于设备记录都按损坏处理。两边序号相等时，这条
781	// 成功记录代表的就是设备最近一次上报，其版本、完整上报配置与首次接受结果时
782	// 保存的发生时间必须分别与影子保存的版本、上报配置和最近上报时间一致
783	// （配置按 JSON 语义比较，时间按同一时刻判断，不因时区表示不同而报错）。
784	// 序号更小则是已被后续上报覆盖的历史记录，不要求与当前影子一致。
785	// 设备当前是否在线不影响本核对；下载结果、失败结果与没有成功结果的阶段
786	// 不保存附带上报序号，也不进入本核对。
787	func checkSuccessReport(campaignID string, dd diskDev, o diskOp, stage string, d *deviceState) error {
788		bad := func(format string, args ...any) error {
789			msg := fmt.Sprintf(format, args...)
790			return fmt.Errorf("%w: campaign %s device %s %s success report %s",
791				ErrCorruptStorage, campaignID, dd.DeviceID, stage, msg)
792		}
793		if o.ResultSeq == 0 {
794			return bad("missing report sequence")
795		}
796		if o.ResultSeq > d.LastSeq {
797			return bad("sequence %d not accepted by device (last accepted %d)", o.ResultSeq, d.LastSeq)
798		}
799		if o.ResultSeq == d.LastSeq {
800			if o.ResultVersion != d.Version {
801				return bad("version %s does not match latest reported version %s", o.ResultVersion, d.Version)
802			}
803			if !rawEqual(o.ResultConfig, d.Reported) {
804				return bad("config does not match latest reported config")
805			}
806			if !o.At.Equal(d.LastReportTime) {
807				return bad("time %s does not match latest report time %s",
808					o.At.Format(time.RFC3339Nano), d.LastReportTime.Format(time.RFC3339Nano))
809			}
810		}
811		return nil
812	}
