814	func validDeviceStatus(status string) bool {
815		switch status {
816		case DevicePending, DeviceDownloading, DeviceReady, DeviceInstalling,
817			DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
818			DeviceAwaitingRollback, DeviceRollingBack,
819			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
820			return true
821		default:
822			return false
823		}
824	}
