826	// isRollbackTerminal 判断状态是否属于回滚相关终态。
827	func isRollbackTerminal(status string) bool {
828		switch status {
829		case DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
830			return true
831		default:
832			return false
833		}
834	}
