836	// isRollbackFlowStatus 判断状态是否处于回滚流程（等待/进行中/任一回滚终态）。
837	func isRollbackFlowStatus(status string) bool {
838		switch status {
839		case DeviceAwaitingRollback, DeviceRollingBack,
840			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
841			return true
842		default:
843			return false
844		}
845	}
