847	// validateDownloadStageDisk 校验 pending（等待下载）与 downloading（下载中）两种
848	// 设备状态与本设备在本活动中保存的下载操作进度一致。两种状态都必须停留在下载
849	// 阶段：pending 表示本设备在本活动中的下载从未领取、尚无下载结果；downloading
850	// 表示下载已经领取、但尚未接受任何下载结果。即使操作标识、时间与结果历史各自
851	// 合法，下载已领取却仍为等待下载、下载未领取却标为下载中，或已经保存下载成功
852	// 或失败结果却仍使用任一状态，都与事实矛盾；阶段已写成安装或回滚同样矛盾。
853	// 核对只看本设备在本活动中的下载操作记录：同批其他设备已领取或下载成功不能替
854	// 它补足进度，设备当前版本恰好等于目标版本、普通上报改变了版本或配置也不能
855	// 代替下载领取与结果。尚未领取下载时没有领取时间、尚无下载结果时没有结果时间，
856	// 是正常缺省；设备后来离线、维护窗口已结束都不使已保存的下载进度失效。矛盾
857	// 一律返回 ErrCorruptStorage，拒绝打开整个存储，不通过调整状态、撤销领取、
858	// 删除历史或补造下载结果消除矛盾。
859	func validateDownloadStageDisk(campaignID string, dd diskDev) error {
860		bad := func(msg string) error {
861			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
862		}
863		switch dd.Status {
864		case DevicePending, DeviceDownloading:
865		default:
866			return nil
867		}
868		if dd.Phase != StageDownload {
869			return bad("download-stage status without download phase")
870		}
871		switch dd.Status {
872		case DevicePending:
873			// 等待下载：下载从未领取、尚无下载结果；没有领取时间与结果时间是正常
874			// 缺省。下载已领取或已有成功/失败结果都与 pending 矛盾。
875			if dd.Download.Claimed || dd.Download.HasResult {
876				return bad("pending state with download claimed or resulted")
877			}
878		case DeviceDownloading:
879			// 下载中：下载已经领取，但还没有接受下载结果（成功或失败都不行）。
880			if !dd.Download.Claimed {
881				return bad("downloading state without download claim")
882			}
883			if dd.Download.HasResult {
884				return bad("downloading state with download result")
885			}
886		}
887		return nil
888	}
889	
890	// validateFailedDeviceDisk 校验 failed 设备的失败阶段、原因与时间与本设备在
891	// 本活动中已接受的失败结果一致。适用于下载失败，以及未开启失败回滚时直接结束
892	// 的安装失败（开启回滚的活动中安装失败会进入回滚流程，不以此状态结束；下载
893	// 失败在两种活动中都直接 failed）。这样的设备失败阶段只能是 download 或
894	// install——回滚阶段的失败另有 rollback_failed 状态，不能把下载失败写成回滚
895	// 阶段；且所选阶段必须恰好对应本设备自己在本活动中已接受的该阶段失败结果：
896	// 设备状态中的失败原因要与结果原因逐字一致，失败时间要与首次接受该结果的时间
897	// 表示同一实际时刻（时区写法不同但时刻相同合法）。
898	// 核对只看本设备在本活动中的操作记录：不能借同批其他设备或其他活动的失败
899	// 记录解释它，也不能用设备当前影子版本替代失败结果。活动结束时间晚于该设备
900	// 失败时间、其他设备仍在处理或已先行失败都不改变本核对。矛盾一律返回
901	// ErrCorruptStorage，拒绝打开整个存储：不能只跳过这台设备提供其余记录，也不
902	// 能改写原因、挪动时间或删去历史使文件可以打开。
903	func validateFailedDeviceDisk(campaignID string, dd diskDev) error {
904		bad := func(msg string) error {
905			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
906		}
907		switch dd.Phase {
908		case StageDownload, StageInstall:
909		default:
910			return bad("failed device phase must be download or install")
911		}
912		// 锚定本设备自己在所选阶段的操作记录：该操作必须已有失败结果。
913		// 开启回滚活动中的安装失败必然进入回滚流程、不会以 failed/install
914		// 结束（由回滚状态校验统一拦截），因此这里只需要核对阶段与结果本身。
915		failedOp := dd.Download
916		if dd.Phase == StageInstall {
917			failedOp = dd.Install
918		}
919		if !failedOp.HasResult || failedOp.Success {
920			return bad("failed device without accepted failed result for its phase")
921		}
922		if failedOp.Reason == "" {
923			return bad("failed result without reason")
924		}
925		if dd.Reason == "" {
926			return bad("failure without reason")
927		}
928		// 设备状态的失败原因必须与已接受失败结果的原因逐字一致。
929		if dd.Reason != failedOp.Reason {
930			return bad("failure reason does not match accepted failed result")
931		}
932		// 设备状态的失败时间必须与首次接受该失败结果的时间表示同一实际时刻；
933		// time.Time 的比较按绝对时刻进行，时区写法不同不视为矛盾。
934		if dd.At.IsZero() || failedOp.At.IsZero() || !dd.At.Equal(failedOp.At) {
935			return bad("failure time does not match accepted failed result time")
936		}
937		return nil
938	}
939	
940	// validateInstallStageDisk 校验 ready（等待安装）与 installing（正在安装）两种
941	// 设备状态与本设备在本活动中保存的操作进度一致。两种状态都必须已有本设备接受
942	// 的下载成功结果并停留在安装阶段：ready 表示安装从未领取、尚无安装结果；
943	// installing 表示安装已经领取、但还没有接受安装结果。即使操作标识、时间与结果
944	// 历史各自合法，已完成安装（安装成功或失败已有结果）的设备也不能解释成仍在
945	// 等待或正在安装，安装已经领取的记录同样不能停在 ready。核对只看本设备本活动
946	// 的下载/安装操作记录：不能借用同批其他设备的下载成功，也不能用设备当前版本
947	// 恰好等于目标版本替代下载或安装结果。尚未领取安装时没有安装领取时间、尚无
948	// 安装结果时没有结果时间，是正常缺省；设备离线、维护窗口已结束或普通上报改变
949	// 了当前版本都不在此核对范围内。矛盾一律返回 ErrCorruptStorage，拒绝打开整个
950	// 存储，不通过调整状态、撤销领取、删除历史或补造结果消除矛盾。
951	func validateInstallStageDisk(campaignID string, dd diskDev) error {
952		bad := func(msg string) error {
953			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
954		}
955		switch dd.Status {
956		case DeviceReady, DeviceInstalling:
957		default:
958			return nil
959		}
960		if dd.Phase != StageInstall {
961			return bad("install-stage status without install phase")
962		}
963		// 两种状态都必须有本设备在本活动中已接受的下载成功结果。
964		if !(dd.Download.HasResult && dd.Download.Success) {
965			return bad("install-stage status without accepted download success")
966		}
967		switch dd.Status {
968		case DeviceReady:
969			// 等待安装：安装从未领取、尚无安装结果；没有安装领取时间与结果时间
970			// 是正常缺省。安装已领取或已有成功/失败结果都与 ready 矛盾。
971			if dd.Install.Claimed || dd.Install.HasResult {
972				return bad("ready state with install claimed or resulted")
973			}
974		case DeviceInstalling:
975			// 正在安装：安装已经领取，但还没有接受安装结果（成功或失败都不行）。
976			if !dd.Install.Claimed {
977				return bad("installing state without install claim")
978			}
979			if dd.Install.HasResult {
980				return bad("installing state with install result")
981			}
982		}
983		return nil
984	}
985	
986	// validateRollbackDisk 校验开启回滚的活动中单台设备的回滚状态自洽。
987	func validateRollbackDisk(campaignID string, dd diskDev) error {
988		bad := func(msg string) error {
989			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
990		}
991		rb := dd.Rollback
992		// 回滚目标只能在首次领取下载时或之后锁定：有目标就必已领取下载。
993		// 反向不成立——领取下载时复查版本不兼容会直接失败，不锁定目标、也不回滚。
994		if dd.RollbackTarget != "" && !dd.Download.Claimed {
995			return bad("rollback target locked before download claim")
996		}
997		// 已领取下载且尚无下载结果，或已有成功下载结果：回滚目标必须已锁定，
998		// 字段缺失与空串按同一种损坏处理。这项要求不因设备进入安装阶段或
999		// 活动已结束而取消——否则安装失败后会留下没有明确恢复版本的回滚待办。
1000		// 不能用当前影子版本、活动目标版本或允许升级列表替代丢失的目标。
1001		// 首次领取前复查版本不兼容、直接在下载阶段失败的设备（下载已有失败
1002		// 结果）允许没有目标：这种失败不进入安装或回滚。
1003		if dd.RollbackTarget == "" && dd.Download.Claimed &&
1004			(!dd.Download.HasResult || dd.Download.Success) {
1005			return bad("missing locked rollback target")
1006		}
1007		// 进入回滚流程的设备必然经过成功下载，目标一定已锁定。
1008		if isRollbackFlowStatus(dd.Status) && dd.RollbackTarget == "" {
1009			return bad("rollback status without locked target")
1010		}
1011		// 回滚流程的唯一入口是“已接受本次安装的失败结果”：等待回滚、正在回滚
1012		// 以及回滚成功/失败/超时的设备，都必须能从本设备在本活动中已经接受的
1013		// 安装结果确认安装失败。安装尚未领取、已领取但没有结果，或安装结果为
1014		// 成功，都不能支持任何回滚状态；即使回滚目标非空、操作标识合法、回滚
1015		// 结果与历史一致或活动已结束，也必须核对这一前提。当前版本恰好等于旧
1016		// 版本、下载失败以及其他设备或其他活动的失败记录都不能代替本次安装失败
1017		// （这里只看本设备本活动保存的安装操作结果本身）。
1018		installFailed := dd.Install.HasResult && !dd.Install.Success
1019		if isRollbackFlowStatus(dd.Status) && !installFailed {
1020			return bad("rollback state without accepted install failure")
1021		}
1022		switch dd.Status {
1023		case DeviceAwaitingRollback:
1024			// 已接受安装失败、回滚尚未领取：回滚无结果。
1025			if dd.Phase != StageRollback || rb.Claimed || rb.HasResult {
1026				return bad("awaiting rollback state mismatch")
1027			}
1028		case DeviceRollingBack:
1029			if dd.Phase != StageRollback || !rb.Claimed || rb.HasResult {
1030				return bad("rolling back state mismatch")
1031			}
1032		case DeviceRollbackSucceeded:
1033			if dd.Phase != StageRollback || !rb.HasResult || !rb.Success {
1034				return bad("rollback succeeded without success result")
1035			}
1036			if rb.ResultVersion != dd.RollbackTarget {
1037				return bad("rollback version mismatch")
1038			}
1039			if _, ok := decodeObject(rb.ResultConfig); !ok {
1040				return bad("rollback config invalid")
1041			}
1042		case DeviceRollbackFailed:
1043			if dd.Phase != StageRollback || !rb.HasResult || rb.Success || rb.Reason == "" {
1044				return bad("rollback failed without failure result")
1045			}
1046		case DeviceRollbackTimeout:
1047			if dd.Phase != StageRollback {
1048				return bad("rollback timeout phase mismatch")
1049			}
1050			// 等待回滚超时（未领取）或正在回滚超时（已领取未完成）都可能。
1051			if rb.HasResult {
1052				return bad("rollback timeout with result")
1053			}
1054		default:
1055			// 其余状态：开启回滚后安装一旦失败必然进入回滚流程，
1056			// 因此这里不能有安装失败，回滚操作也必须从未被领取或提交；
1057			// 但回滚目标可能因已领取下载而存在（下载失败/超时/成功等）。
1058			if dd.Install.HasResult && !dd.Install.Success {
1059				return bad("install failure without rollback state")
1060			}
1061			if rb.Claimed || rb.HasResult {
1062				return bad("rollback progressed without install failure")
1063			}
1064		}
1065		return nil
1066	}
1067

