5		"testing"
6		"time"
7	)
8	
9	// 本文件保护“接受安装失败后才进入回滚”这一前提在打开本地存储时同样生效：
10	// 开启安装失败回滚的活动中，只要某台设备处于等待回滚、正在回滚、回滚成功、
11	// 回滚失败或回滚超时，就必须能从该设备在同一活动中已经接受的安装结果确认
12	// 安装失败。安装尚未领取、已领取但没有结果，或安装结果为成功，都不能支持
13	// 这些回滚状态；下载失败、其他设备或其他活动的失败记录也不能代替本次安装
14	// 失败。发现矛盾时 Open 返回 ErrCorruptStorage，整个存储不得进入可用状态，
15	// 原文件内容保持不变。
16	
17	// installFailAt 是测试时间线中安装失败被接受的时刻：
18	// 领取下载 +2m、下载成功 +3m、领取安装 +4m、安装失败 +5m。
19	func installFailAt(base time.Time) time.Time { return base.Add(5 * time.Minute) }
20	
21	// buildRollingBase 构造一台处于“正在回滚”的设备：完成下载、安装失败被接受、
22	// 再领取回滚但不完成。withReport 时在等待回滚期间插入一条 seq=2 的普通上报
23	// （版本 v9、空配置），用于让伪造的安装成功结果拥有更小序号、不与当前影子
24	// 对内容；普通上报不改变已接受的安装失败与回滚待办。
25	func buildRollingBase(t *testing.T, withReport bool) (*Store, CampaignSpec) {
26		t.Helper()
27		s := setupUpgrade(t, "d1")
28		spec := rbSpec()
29		createCampaign(t, s, spec)
30		bringOnline(t, s, "d1")
31		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
32		if withReport {
33			if err := s.Report("d1", 2, upBase.Add(6*time.Minute), "v9", json.RawMessage(`{}`)); err != nil {
34				t.Fatalf("plain report: %v", err)
35			}
36		}
37		rb, err := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
38		if err != nil || rb == nil || rb.Kind != StageRollback {
39			t.Fatalf("claim rollback: %v %+v", err, rb)
40		}
41		return s, spec
42	}
