83	// removeInstallHistory 删除该设备保存的安装结果历史条目，返回被删条目是否存在。
84	func removeInstallHistory(doc map[string]any, campaignID, deviceID string) bool {
85		camp := campaignDoc(doc, campaignID)
86		raw, _ := camp["results"].([]any)
87		kept := make([]any, 0, len(raw))
88		found := false
89		for _, r := range raw {
90			rec := r.(map[string]any)
91			if rec["deviceId"] == deviceID && rec["stage"] == StageInstall {
92				found = true
93				continue
94			}
95			kept = append(kept, rec)
96		}
97		camp["results"] = kept
98		return found
99	}
