101	// setInstallNoResult 把安装操作改写为“已领取但没有结果”（claimed=true 时）
102	// 或“尚未领取”（claimed=false 时），并清掉全部结果字段；安装失败历史同步删除。
103	// 改写后除“缺少本设备本次安装失败”外的其余记录保持自洽。
104	func setInstallNoResult(doc map[string]any, campaignID, deviceID string, claimed bool) {
105		inst := installOpDoc(doc, campaignID, deviceID)
106		inst["claimed"] = claimed
107		if claimed {
108			if _, ok := inst["claimedAt"]; !ok {
109				inst["claimedAt"] = "2026-10-02T12:04:00Z"
110			}
111		} else {
112			delete(inst, "claimedAt")
113		}
114		inst["hasResult"] = false
115		for _, k := range []string{"success", "reason", "at", "resultSeq", "resultVersion", "resultConfig"} {
116			delete(inst, k)
117		}
118		if !removeInstallHistory(doc, campaignID, deviceID) {
119			panic("test setup: install history missing")
120		}
121	}
122	
123	// setInstallSuccess 把安装操作改写为一条内容自洽的“安装成功”已接受结果
124	// （seq=1，版本等于活动目标 v2，空对象配置），历史条目同步改为安装成功。
125	// 当设备最近已接受更大序号（seq=2 的普通上报或回滚上报）时，这条 seq=1 的
126	// 成功记录属于被后续上报覆盖的历史，恢复核对不要求它与当前影子一致，因此
127	// 除“安装成功不能支持回滚状态”外记录完全合法。
128	func setInstallSuccess(doc map[string]any, campaignID, deviceID string) {
129		inst := installOpDoc(doc, campaignID, deviceID)
130		inst["claimed"] = true
131		if _, ok := inst["claimedAt"]; !ok {
132			inst["claimedAt"] = "2026-10-02T12:04:00Z"
133		}
134		inst["hasResult"] = true
135		inst["success"] = true
136		delete(inst, "reason")
137		if _, ok := inst["at"]; !ok {
138			inst["at"] = "2026-10-02T12:05:00Z"
139		}
140		inst["resultSeq"] = 1
141		inst["resultVersion"] = "v2"
142		inst["resultConfig"] = map[string]any{}
143		camp := campaignDoc(doc, campaignID)
144		raw, _ := camp["results"].([]any)
145		replaced := false
146		for _, r := range raw {
147			rec := r.(map[string]any)
148			if rec["deviceId"] == deviceID && rec["stage"] == StageInstall {
149				rec["success"] = true
150				delete(rec, "reason")
151				rec["version"] = "v2"
152				replaced = true
153			}
154		}
155		if !replaced {
156			panic("test setup: install history missing")
157		}
158	}
