160	// setDownloadFailure 把成功下载改写为下载失败（带原因），安装改为尚未领取、
161	// 安装失败历史删除，用来证明下载失败不能代替本次安装失败。回滚目标仍保留。
162	func setDownloadFailure(doc map[string]any, campaignID, deviceID string) {
163		dev := campaignDeviceDoc(doc, campaignID, deviceID)
164		dl := dev["download"].(map[string]any)
165		dl["hasResult"] = true
166		dl["success"] = false
167		dl["reason"] = "dl down"
168		if _, ok := dl["at"]; !ok {
169			dl["at"] = dl["claimedAt"]
170		}
171		inst := dev["install"].(map[string]any)
172		inst["claimed"] = false
173		delete(inst, "claimedAt")
174		inst["hasResult"] = false
175		for _, k := range []string{"success", "reason", "at", "resultSeq", "resultVersion", "resultConfig"} {
176			delete(inst, k)
177		}
178		removeInstallHistory(doc, campaignID, deviceID)
179		camp := campaignDoc(doc, campaignID)
180		raw, _ := camp["results"].([]any)
181		for _, r := range raw {
182			rec := r.(map[string]any)
183			if rec["deviceId"] == deviceID && rec["stage"] == StageDownload {
184				rec["success"] = false
185				rec["reason"] = "dl down"
186				delete(rec, "version")
187			}
188		}
189	}
