218	// TestRestoreRollbackRequiresInstallFailure 保护核心修复：正在回滚与回滚终态
219	// 此前缺少“已接受本次安装失败”的核对，安装尚未领取、已领取但没有结果、安装
220	// 成功，或只有下载失败的设备也能被恢复成回滚状态、查到回滚待办。这些自洽
221	// （回滚目标非空、操作标识合法、回滚结果与历史一致）的矛盾记录现在都必须在
222	// Open 时整体拒绝。
223	func TestRestoreRollbackRequiresInstallFailure(t *testing.T) {
224		// statusBases 给出每种“修复前未核对”的回滚状态及其磁盘构造方式。
225		// 伪造安装成功/下载失败等情形依赖设备最近已接受 seq=2 的上报，
226		// 因此基座统一带一条等待回滚期间的普通上报（不否定安装失败）。
227		type base struct {
228			status string
229			build  func(t *testing.T) (*Store, CampaignSpec)
230		}
231		bases := []base{
232			{DeviceRollingBack, func(t *testing.T) (*Store, CampaignSpec) {
233				return buildRollingBase(t, true)
234			}},
235			{DeviceRollbackSucceeded, func(t *testing.T) (*Store, CampaignSpec) {
236				s, spec := buildRollingBase(t, true)
237				finishRollbackSuccess(t, s, spec, 3)
238				return s, spec
239			}},
240			{DeviceRollbackFailed, func(t *testing.T) (*Store, CampaignSpec) {
241				s, spec := buildRollingBase(t, true)
242				finishRollbackFailure(t, s, spec)
243				return s, spec
244			}},
245			{DeviceRollbackTimeout, func(t *testing.T) (*Store, CampaignSpec) {
246				s, spec := buildRollingBase(t, true)
247				timeoutRollingBase(t, s, spec)
248				return s, spec
249			}},
250		}
251		for _, b := range bases {
252			for _, mc := range rollbackPremiseCases() {
253				name := b.status + "/" + mc.name
254				t.Run(name, func(t *testing.T) {
255					s, spec := b.build(t)
256					if d := findDevice(mustGetCampaign(s, spec.ID), "d1"); d.Status != b.status {
257						t.Fatalf("precondition status: got %s want %s", d.Status, b.status)
258					}
259					dir := closeStore(t, s)
260					original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
261						mc.mutate(doc, spec.ID, "d1")
262					})
263					assertReopenCorrupt(t, dir, original)
264				})
265			}
266		}
267	}
