269	// TestRestoreAwaitingRollbackTimeoutRequiresInstallFailure 覆盖等待回滚超时
270	// （回滚未领取、无回滚结果）这一形态：它同样必须有已接受的安装失败，
271	// 不能因为没有回滚领取和结果就把缺少安装失败当成正常记录。
272	func TestRestoreAwaitingRollbackTimeoutRequiresInstallFailure(t *testing.T) {
273		for _, mc := range rollbackPremiseCases() {
274			t.Run(mc.name, func(t *testing.T) {
275				s := setupUpgrade(t, "d1")
276				spec := rbSpec()
277				createCampaign(t, s, spec)
278				bringOnline(t, s, "d1")
279				awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
280				if err := s.Report("d1", 2, upBase.Add(6*time.Minute), "v9", json.RawMessage(`{}`)); err != nil {
281					t.Fatalf("plain report: %v", err)
282				}
283				// 不领取回滚，直接推进到截止：等待回滚超时（回滚未领取、无结果）。
284				if err := s.AdvanceCampaign(spec.ID, upBase.Add(2*time.Hour)); err != nil {
285					t.Fatal(err)
286				}
287				if d := findDevice(mustGetCampaign(s, spec.ID), "d1"); d.Status != DeviceRollbackTimeout {
288					t.Fatalf("precondition: %+v", d)
289				}
290				dir := closeStore(t, s)
291				original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
292					mc.mutate(doc, spec.ID, "d1")
293				})
294				assertReopenCorrupt(t, dir, original)
295			})
296		}
297	}
