299	// TestRestoreRollbackPremiseOtherFailuresDontCount 证明安装失败前提必须是
300	// “本设备、本活动、本次安装”的失败：同活动另一台设备的安装失败，以及另一个
301	// 正常活动里的回滚记录，都不能代替本设备本次安装失败；即使其余设备与活动
302	// 全部正常，整个存储仍必须拒绝打开，原文件保持不变。
303	func TestRestoreRollbackPremiseOtherFailuresDontCount(t *testing.T) {
304		s := setupUpgrade(t, "d1", "d2", "d3")
305		spec := upSpec()
306		spec.Devices = []string{"d1", "d2"}
307		spec.BatchSize = 2
308		spec.RollbackOnFailure = true
309		createCampaign(t, s, spec)
310		bringOnline(t, s, "d1")
311		bringOnline(t, s, "d2")
312		// 两台设备都安装失败、进入回滚：d2 保留合法的安装失败记录。
313		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
314		awaitRollback(t, s, spec, "d2", upBase.Add(12*time.Minute))
315		if _, err := s.Claim(spec.ID, "d1", upBase.Add(20*time.Minute)); err != nil {
316			t.Fatalf("claim d1 rollback: %v", err)
317		}
318	
319		// 另一个完全正常的回滚活动（d3），重开本应照常可用。
320		other := rbSpec()
321		other.ID = "cmp-other"
322		other.Devices = []string{"d3"}
323		createCampaign(t, s, other)
324		bringOnline(t, s, "d3")
325		inID, _ := awaitRollback(t, s, other, "d3", upBase.Add(22*time.Minute))
326		if inID == "" {
327			t.Fatal("other campaign setup")
328		}
329	
330		dir := closeStore(t, s)
331		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
332			// d1 的安装失败被抹成“已领取但没有结果”，d2 与 cmp-other 不动。
333			setInstallNoResult(doc, spec.ID, "d1", true)
334		})
335		// d2、d3 的合法回滚记录不能让存储部分可用：整个存储必须原样拒绝。
336		assertReopenCorrupt(t, dir, original)
337	}
