339	// TestRestoreLegitRollbackStatesKeepProgress 保护合法回滚记录的恢复行为不变：
340	// 安装失败后等待回滚、正在回滚、回滚成功、回滚失败、等待回滚超时与正在回滚
341	// 超时都按原进度、锁定目标与安装失败原因/时间恢复；这些记录即使缺回滚领取
342	// 或回滚结果（超时形态）也照常打开。
343	func TestRestoreLegitRollbackStatesKeepProgress(t *testing.T) {
344		failAt := installFailAt(upBase)
345	
346		t.Run("awaiting rollback", func(t *testing.T) {
347			s := setupUpgrade(t, "d1")
348			spec := rbSpec()
349			createCampaign(t, s, spec)
350			bringOnline(t, s, "d1")
351			awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
352			dir := closeStore(t, s)
353			s2, err := Open(dir)
354			if err != nil {
355				t.Fatalf("reopen: %v", err)
356			}
357			defer s2.Close()
358			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
359			if d.Status != DeviceAwaitingRollback || d.RollbackTarget != "v1" ||
360				d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
361				t.Fatalf("awaiting rollback restored: %+v", d)
362			}
363			w, _ := s2.GetDeviceWork("d1")
364			if w.Pending == nil || w.Pending.Kind != StageRollback ||
365				w.PendingClaimed || w.Pending.TargetVersion != "v1" {
366				t.Fatalf("rollback todo restored: %+v", w)
367			}
368		})
369	
370		t.Run("rolling back", func(t *testing.T) {
371			s, spec := buildRollingBase(t, false)
372			rbBefore := findDevice(mustGetCampaign(s, spec.ID), "d1").RollbackID
373			dir := closeStore(t, s)
374			s2, err := Open(dir)
375			if err != nil {
376				t.Fatalf("reopen: %v", err)
377			}
378			defer s2.Close()
379			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
380			if d.Status != DeviceRollingBack || d.RollbackTarget != "v1" ||
381				d.RollbackID != rbBefore ||
382				d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
383				t.Fatalf("rolling back restored: %+v", d)
384			}
385			again, err := s2.Claim(spec.ID, "d1", upBase.Add(85*time.Minute))
386			if err != nil || again == nil || again.ID != rbBefore {
387				t.Fatalf("claimed rollback id stable: %v %+v", err, again)
388			}
389		})
390	
391		t.Run("rollback succeeded", func(t *testing.T) {
392			s, spec := buildRollingBase(t, false)
393			finishRollbackSuccess(t, s, spec, 2)
394			dir := closeStore(t, s)
395			s2, err := Open(dir)
396			if err != nil {
397				t.Fatalf("reopen: %v", err)
398			}
399			defer s2.Close()
400			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
401			if d.Status != DeviceRollbackSucceeded || d.RollbackTarget != "v1" ||
402				!d.RollbackResult || !d.RollbackSuccess ||
403				d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
404				t.Fatalf("rollback success restored: %+v", d)
405			}
406			if sh, _ := s2.Get("d1"); sh.Version != "v1" {
407				t.Fatalf("shadow version restored: %s", sh.Version)
408			}
409		})
410	
411		t.Run("rollback failed", func(t *testing.T) {
412			s, spec := buildRollingBase(t, false)
413			finishRollbackFailure(t, s, spec)
414			dir := closeStore(t, s)
415			s2, err := Open(dir)
416			if err != nil {
417				t.Fatalf("reopen: %v", err)
418			}
419			defer s2.Close()
420			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
421			if d.Status != DeviceRollbackFailed || d.RollbackReason != "rb boom" ||
422				!d.RollbackAt.Equal(upBase.Add(9*time.Minute)) ||
423				d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
424				t.Fatalf("rollback failure restored: %+v", d)
425			}
426		})
427	
428		t.Run("awaiting rollback timeout", func(t *testing.T) {
429			s := setupUpgrade(t, "d1")
430			spec := rbSpec()
431			createCampaign(t, s, spec)
432			bringOnline(t, s, "d1")
433			awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
434			if err := s.AdvanceCampaign(spec.ID, upBase.Add(2*time.Hour)); err != nil {
435				t.Fatal(err)
436			}
437			dir := closeStore(t, s)
438			s2, err := Open(dir)
439			if err != nil {
440				t.Fatalf("reopen: %v", err)
441			}
442			defer s2.Close()
443			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
444			// 等待回滚超时：可以没有回滚领取和结果，但安装失败原因/时间保留。
445			if d.Status != DeviceRollbackTimeout || d.RollbackResult ||
446				d.RollbackID == "" || d.RollbackTarget != "v1" ||
447				d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
448				t.Fatalf("awaiting-timeout restored: %+v", d)
449			}
450		})
451	
452		t.Run("rolling back timeout", func(t *testing.T) {
453			s, spec := buildRollingBase(t, false)
454			timeoutRollingBase(t, s, spec)
455			dir := closeStore(t, s)
456			s2, err := Open(dir)
457			if err != nil {
458				t.Fatalf("reopen: %v", err)
459			}
460			defer s2.Close()
461			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
462			// 正在回滚超时：已领取回滚但可以没有回滚结果，安装失败仍保留。
463			if d.Status != DeviceRollbackTimeout || d.RollbackResult ||
464				d.RollbackTarget != "v1" ||
465				d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
466				t.Fatalf("rolling-timeout restored: %+v", d)
467			}
468		})
469	}
