488			t.Fatalf("rollback with later report restored: %+v", d)
489		}
490		w, _ := s2.GetDeviceWork("d1")
491		if w.Pending == nil || w.Pending.Kind != StageRollback ||
492			w.Pending.TargetVersion != "v1" || w.Version != "v9" {
493			t.Fatalf("todo target stays locked while shadow moved: %+v", w)
494		}
495	}
496

