package shadow

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// rbSpec 返回一个开启安装失败回滚的单设备活动规格（窗口 12:00–13:00，截止 14:00）。
func rbSpec() CampaignSpec {
	spec := upSpec()
	spec.Devices = []string{"d1"}
	spec.BatchSize = 1
	spec.RollbackOnFailure = true
	return spec
}

// awaitRollback 完成下载并令安装失败，使开启回滚活动中的设备进入等待回滚。
// 时间线（相对 at）：领取下载 at、下载成功 at+1m、领取安装 at+2m、安装失败 at+3m。
// 返回安装操作标识与安装失败被接受的时间。
func awaitRollback(t *testing.T, s *Store, spec CampaignSpec, id string, at time.Time) (string, time.Time) {
	t.Helper()
	dl, err := s.Claim(spec.ID, id, at)
	if err != nil || dl == nil || dl.Kind != StageDownload {
		t.Fatalf("claim download: %v %+v", err, dl)
	}
	if err := s.SubmitResult(OperationResult{
		CampaignID: spec.ID, DeviceID: id, OperationID: dl.ID,
		At: at.Add(time.Minute), Success: true,
	}); err != nil {
		t.Fatalf("download result: %v", err)
	}
	in, err := s.Claim(spec.ID, id, at.Add(2*time.Minute))
	if err != nil || in == nil || in.Kind != StageInstall {
		t.Fatalf("claim install: %v %+v", err, in)
	}
	failAt := at.Add(3 * time.Minute)
	if err := s.SubmitResult(OperationResult{
		CampaignID: spec.ID, DeviceID: id, OperationID: in.ID,
		At: failAt, Success: false, Reason: "install broken",
	}); err != nil {
		t.Fatalf("install failure: %v", err)
	}
	return in.ID, failAt
}

// 未开启回滚（默认）时安装失败沿用现有行为：设备直接失败，不锁定/等待回滚。
func TestRollbackDisabledKeepsLegacyBehavior(t *testing.T) {
	s := setupUpgrade(t, "d1")
	spec := upSpec()
	spec.Devices = []string{"d1"}
	spec.BatchSize = 1
	createCampaign(t, s, spec)
	bringOnline(t, s, "d1")

	_, failAt := awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
	v, _ := s.GetCampaign(spec.ID)
package shadow

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// rewriteStore 读入已保存的存储文件，用 mutate 改写后写回，返回写回后的字节
// （即拒绝打开时必须原样保留的损坏内容）。
func rewriteStoreBytes(t *testing.T, dir string, mutate func(map[string]any)) []byte {
	t.Helper()
	path := filepath.Join(dir, storeFileName)
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var doc map[string]any
	if err := json.Unmarshal(data, &doc); err != nil {
		t.Fatal(err)
	}
	mutate(doc)
	out, err := json.Marshal(doc)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, out, 0o644); err != nil {
		t.Fatal(err)
	}
	return out
}

func campaignDoc(doc map[string]any, id string) map[string]any {
	return doc["campaigns"].(map[string]any)[id].(map[string]any)
}

func resultDocs(doc map[string]any, id string) []map[string]any {
	raw := campaignDoc(doc, id)["results"].([]any)
	out := make([]map[string]any, len(raw))
	for i, r := range raw {
		out[i] = r.(map[string]any)
	}
	return out
}

// assertReopenCorrupt 校验被改写的存储拒绝打开，且原文件内容保留不变。
func assertReopenCorrupt(t *testing.T, dir string, original []byte) {
	t.Helper()
	s, err := Open(dir)
	if err == nil {
		s.Close()
		t.Fatalf("expected ErrCorruptStorage")
	}
	if !errors.Is(err, ErrCorruptStorage) {
		t.Fatalf("error must wrap ErrCorruptStorage: %v", err)
	}
	data, rerr := os.ReadFile(filepath.Join(dir, storeFileName))
	if rerr != nil {
		t.Fatal(rerr)
	}
	// 拒绝打开后重写的内容必须原样保留，不能被空数据或“修复”覆盖。
	if string(data) != string(original) {
		// original 是改写后的字节（即磁盘现状），这里只确认 Open 未再改动文件。
		t.Fatalf("store file modified by rejected open")
	}
}

