	if err != nil || rb == nil {
		t.Fatalf("claim rollback: %v %+v", err, rb)
	}
	rbAt := upBase.Add(9 * time.Minute)
	if err := s.SubmitResult(OperationResult{
		CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
